function num(value){if(typeof value==='number')return Number.isFinite(value)?value:NaN;const s=String(value??'').trim().replace(/\s/g,'');if(!s)return NaN;let norm=s;if(s.includes(',')&&s.includes('.'))norm=s.lastIndexOf(',')>s.lastIndexOf('.')?s.replace(/\./g,'').replace(',','.'):s.replace(/,/g,'');else if(s.includes(','))norm=s.replace(',','.');if(!/^[+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?$/.test(norm))return NaN;return Number(norm)}
const avg=v=>v.reduce((a,b)=>a+b,0)/v.length;
const variance=v=>v.length>1?v.reduce((a,b)=>a+(b-avg(v))**2,0)/(v.length-1):NaN;
const sd=v=>Math.sqrt(variance(v));
const quantile=(v,p)=>{let a=[...v].sort((x,y)=>x-y),k=(a.length-1)*p,l=Math.floor(k),h=Math.ceil(k);return a.length?a[l]+(a[h]-a[l])*(k-l):NaN};
