// Stable Lanczos log Gamma and regularized incomplete beta; used for Student t and F p-values.
function logGamma(z){let p=[0.99999999999980993,676.5203681218851,-1259.1392167224028,771.32342877765313,-176.61502916214059,12.507343278686905,-.13857109526572012,9.9843695780195716e-6,1.5056327351493116e-7];if(z<.5)return Math.log(Math.PI)-Math.log(Math.sin(Math.PI*z))-logGamma(1-z);z-=1;let x=p[0];for(let i=1;i<p.length;i++)x+=p[i]/(z+i);let t=z+7.5;return .5*Math.log(2*Math.PI)+(z+.5)*Math.log(t)-t+Math.log(x)}
function betaFraction(a,b,x){const eps=3e-14,fpMin=1e-300;let qab=a+b,qap=a+1,qam=a-1,c=1,d=1-qab*x/qap;if(Math.abs(d)<fpMin)d=fpMin;d=1/d;let h=d;for(let m=1;m<=230;m++){let m2=2*m,aa=m*(b-m)*x/((qam+m2)*(a+m2));d=1+aa*d;if(Math.abs(d)<fpMin)d=fpMin;c=1+aa/c;if(Math.abs(c)<fpMin)c=fpMin;d=1/d;h*=d*c;aa=-(a+m)*(qab+m)*x/((a+m2)*(qap+m2));d=1+aa*d;if(Math.abs(d)<fpMin)d=fpMin;c=1+aa/c;if(Math.abs(c)<fpMin)c=fpMin;d=1/d;let del=d*c;h*=del;if(Math.abs(del-1)<eps)break}return h}
function betai(a,b,x){if(x<=0)return 0;if(x>=1)return 1;let bt=Math.exp(logGamma(a+b)-logGamma(a)-logGamma(b)+a*Math.log(x)+b*Math.log1p(-x));return clamp(x<(a+1)/(a+b+2)?bt*betaFraction(a,b,x)/a:1-bt*betaFraction(b,a,1-x)/b,0,1)}
const tCDF=(t,df)=>{if(!Number.isFinite(df)||df<=0)return NaN;if(t===Infinity)return 1;if(t===-Infinity)return 0;let x=betai(df/2,.5,df/(df+t*t));return t>=0?1-.5*x:.5*x};
const fCDF=(x,d1,d2)=>x<=0?0:betai(d1/2,d2/2,d1*x/(d1*x+d2));
function tp(t,df,alternative='two-sided'){let c=tCDF(t,df);return alternative==='greater'?1-c:alternative==='less'?c:2*Math.min(c,1-c)}
function pairedPairs(project,xa,ya){let ci=project.dataset.columns.findIndex(x=>x.id===xa),cj=project.dataset.columns.findIndex(x=>x.id===ya);return project.dataset.rows.map(row=>[num(row[ci]),num(row[cj])]).filter(([x,y])=>Number.isFinite(x)&&Number.isFinite(y))}
function numericColumn(project,key){let j=project.dataset.columns.findIndex(x=>x.id===key);return j<0?[]:project.dataset.rows.map(r=>num(r[j])).filter(Number.isFinite)}
function categoryValues(project,key){let j=project.dataset.columns.findIndex(x=>x.id===key);return j<0?[]:project.dataset.rows.map(r=>String(r[j]??'').trim())}
function groupArrays(project,measure,group){let i=project.dataset.columns.findIndex(x=>x.id===measure),g=project.dataset.columns.findIndex(x=>x.id===group);const bins={};if(i<0||g<0)return bins;project.dataset.rows.forEach(row=>{let n=num(row[i]),label=String(row[g]??'').trim();if(Number.isFinite(n)&&label)(bins[label]??=[]).push(n)});return bins}
function pearson(pairs){let xs=pairs.map(p=>p[0]),ys=pairs.map(p=>p[1]),n=pairs.length;if(n<3)return null;let mx=avg(xs),my=avg(ys),xx=sum(xs.map(x=>(x-mx)**2)),yy=sum(ys.map(y=>(y-my)**2)),xy=sum(pairs.map(([x,y])=>(x-mx)*(y-my)));if(xx<=0||yy<=0)return null;let r=xy/Math.sqrt(xx*yy),slope=xy/xx,intercept=my-slope*mx,t=r*Math.sqrt((n-2)/Math.max(1e-15,1-r*r));return {n,r,slope,intercept,r2:r*r,p:tp(t,n-2),pred:x=>intercept+slope*x};}
function ranks(x){let a=x.map((v,i)=>({v,i})).sort((a,b)=>a.v-b.v),r=Array(x.length);for(let i=0;i<a.length;){let j=i;while(j+1<a.length&&a[j+1].v===a[i].v)j++;for(let k=i;k<=j;k++)r[a[k].i]=(i+j+2)/2;i=j+1}return r}
function spearman(p){let rx=ranks(p.map(x=>x[0])),ry=ranks(p.map(x=>x[1]));return pearson(rx.map((v,i)=>[v,ry[i]]))}
function jarqueBera(x){let n=x.length;if(n<8)return null;let mean=avg(x),m2=avg(x.map(v=>(v-mean)**2));if(m2<=0)return null;let skew=avg(x.map(v=>((v-mean)/Math.sqrt(m2))**3)),kurt=avg(x.map(v=>((v-mean)/Math.sqrt(m2))**4)),jb=n/6*(skew*skew+(kurt-3)**2/4);return {n,skew,kurt,jb,p:Math.exp(-jb/2)}}
function oneSample(x,mu,alt){let n=x.length;if(n<2)return null;let s=sd(x),delta=avg(x)-mu,t=s===0?(delta===0?0:delta>0?Infinity:-Infinity):delta/(s/Math.sqrt(n));return {n,mean:avg(x),sd:s,t,df:n-1,p:tp(t,n-1,alt),diff:delta}}
function welch(a,b,alt){if(a.length<2||b.length<2)return null;let v1=variance(a)/a.length,v2=variance(b)/b.length,den=v1+v2;if(den<=0)return null;let df=den*den/(v1*v1/(a.length-1)+v2*v2/(b.length-1)),t=(avg(a)-avg(b))/Math.sqrt(den);return {n1:a.length,n2:b.length,mean1:avg(a),mean2:avg(b),t,df,p:tp(t,df,alt)}}
function anova(groups){let vals=Object.values(groups).filter(v=>v.length>0),k=vals.length,N=vals.reduce((a,v)=>a+v.length,0);if(k<2||N<=k)return null;let all=vals.flat(),grand=avg(all),ssb=sum(vals.map(v=>v.length*(avg(v)-grand)**2)),ssw=sum(vals.map(v=>sum(v.map(n=>(n-avg(v))**2)))),df1=k-1,df2=N-k;let F=ssw===0?(ssb===0?0:Infinity):(ssb/df1)/(ssw/df2),p=F===Infinity?0:1-fCDF(F,df1,df2);return {k,N,F,p,df1,df2,ssb,ssw,eta2:ssb/(ssb+ssw)||0}}
const pfRPN=row=>{let scores=['s','o','d'].map(k=>num(row[k]));return scores.every(x=>Number.isInteger(x)&&x>=1&&x<=10)?scores.reduce((a,b)=>a*b,1):null};
const pfNewRPN=row=>{let scores=['ns','no','nd'].map(k=>num(row[k]));return scores.every(x=>Number.isInteger(x)&&x>=1&&x<=10)?scores.reduce((a,b)=>a*b,1):null};
