function plotShell(ymin,ymax,xmin,xmax,title,xlab,ylab){let w=760,h=360,pl=65,pr=24,pt=35,pb=61,pw=w-pl-pr,ph=h-pt-pb;let tx=x=>pl+(x-xmin)/(xmax-xmin||1)*pw,ty=y=>pt+ph-(y-ymin)/(ymax-ymin||1)*ph;let svg=`<svg viewBox="0 0 760 360" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="${esc(title)}">${svgText(20,19,title,'fill="#e8f3f8" font-size="14" font-weight="700"')}`;for(let i=0;i<=5;i++){let val=ymin+(ymax-ymin)*i/5,y=ty(val);svg+=`<line x1="${pl}" x2="${w-pr}" y1="${y}" y2="${y}" stroke="#284452" stroke-dasharray="3 5"/>${svgText(pl-9,y+4,fmt(val,2),'text-anchor="end" font-size="10"')}`}for(let i=0;i<=5;i++){let val=xmin+(xmax-xmin)*i/5,x=tx(val);svg+=`${svgText(x,h-pb+20,fmt(val,1),'text-anchor="middle" font-size="10"')}`}svg+=svgText(w/2,h-8,xlab,'text-anchor="middle"')+`<text x="14" y="${h/2}" transform="rotate(-90 14 ${h/2})" text-anchor="middle" fill="#a6c0cc" font-size="12">${esc(ylab)}</text>`;return {svg,tx,ty,close:'</svg>',pl,pr,pt,pb,w,h,pw,ph}}
function scatterSVG(pairs,title,xlab,ylab,fit=null){if(!pairs.length)return '';let [xmin,xmax]=niceRange(pairs.map(p=>p[0])),[ymin,ymax]=niceRange(pairs.map(p=>p[1]));if(fit){let ya=fit.intercept+fit.slope*xmin,yb=fit.intercept+fit.slope*xmax;[ymin,ymax]=niceRange([...pairs.map(p=>p[1]),ya,yb])}let s=plotShell(ymin,ymax,xmin,xmax,title,xlab,ylab),out=s.svg;if(fit)out+=`<line x1="${s.tx(xmin)}" y1="${s.ty(fit.intercept+fit.slope*xmin)}" x2="${s.tx(xmax)}" y2="${s.ty(fit.intercept+fit.slope*xmax)}" stroke="#20d2a2" stroke-width="3"/>`;for(let [x,y] of pairs)out+=`<circle cx="${s.tx(x)}" cy="${s.ty(y)}" r="4.2" fill="#76b9ff" stroke="#102b3b" stroke-width="1.3"><title>${esc(xlab)}=${fmt(x)} · ${esc(ylab)}=${fmt(y)}</title></circle>`;return out+s.close}
