function lineSVG(values,limits,title,xlab='Beobachtung'){let n=values.length,[lo,hi]=niceRange([...values,...(limits||[]).filter(Number.isFinite)]),s=plotShell(lo,hi,1,Math.max(2,n),title,xlab,'Messwert'),points=values.map((v,i)=>`${s.tx(i+1)},${s.ty(v)}`).join(' '),out=s.svg+`<polyline points="${points}" fill="none" stroke="#6fb7ff" stroke-width="2.6"/>`;values.forEach((v,i)=>out+=`<circle cx="${s.tx(i+1)}" cy="${s.ty(v)}" r="3" fill="#20d2a2"/>`);if(limits)limits.forEach((v,i)=>{if(!Number.isFinite(v))return;let label=['LCL','Mittelwert','UCL'][i],clr=i===1?'#ffaa61':'#ff7b7f';out+=`<line x1="${s.pl}" y1="${s.ty(v)}" x2="${s.w-s.pr}" y2="${s.ty(v)}" stroke="${clr}" stroke-width="1.7" stroke-dasharray="5 4"/>${svgText(s.w-s.pr-6,s.ty(v)-5,label,'text-anchor="end" font-size="10"')}`});return out+s.close}
