if(tool==='control'){if(x.length<3)return empty('Mindestens 3 sequenzielle Einzelwerte nötig.');let mean=avg(x),mrs=x.slice(1).map((v,i)=>Math.abs(v-x[i])),mrb=avg(mrs),lcl=mean-2.66*mrb,ucl=mean+2.66*mrb;let outside=x.filter(v=>v<lcl||v>ucl).length;return {valid:true,chart:lineSVG(x,[lcl,mean,ucl],title),stats:[stat('n',x.length),stat('Mittellinie',mean),stat('MR̄',mrb),stat('LCL',lcl),stat('UCL',ucl),stat('Außer Grenzen',outside),stat('MR UCL (3,267×MR̄)',3.267*mrb)],message:'Individuals-Regelkarte mit Grenzen X̄ ± 2,66×MR̄. Reihenfolge der Zeilen muss der Prozessreihenfolge entsprechen. Punkte außerhalb der Grenzen zeigen potenzielle Sonderursachen; vollständige Run Rules sind nicht implementiert.'}}
