function pfmeaView(p){let rows=p.pfmea;const columns=[['process','Prozess / Funktion'],['mode','Fehlermöglichkeit'],['effect','Auswirkung'],['cause','Ursache'],['prevention','Vorbeugung'],['detection','Entdeckung'],['s','S'],['o','O'],['d','D'],['action','Maßnahme'],['owner','Verantwortlich'],['due','Termin'],['ns','S neu'],['no','O neu'],['nd','D neu']];let critical=rows.filter(r=>pfRPN(r)>=160||num(r.s)>=9).length;return `<div class="panel"><div class="panel-head"><div><h2>PFMEA · Prozess-Fehlermöglichkeits- und Einflussanalyse</h2><p class="sub">S/O/D jeweils 1–10, RPN = S × O × D. Nach Maßnahmen S/O/D neu erfassen → Rest-RPN.</p></div><div class="action-bar"><span class="tag amber">${critical} erhöhte Priorität*</span><button class="btn small outline" data-action="export-pfmea">↓ PFMEA CSV</button><button class="btn small primary" data-action="add-fmea">+ Fehlermöglichkeit</button></div></div>${rows.length?`<div class="scroll"><table class="grid-table" style="min-width:1850px"><thead><tr><th>#</th>${columns.slice(0,9).map(c=>`<th>${esc(c[1])}</th>`).join('')}<th>RPN</th>${columns.slice(9).map(c=>`<th>${esc(c[1])}</th>`).join('')}<th>Rest-RPN</th><th></th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td class="rownum">${i+1}</td>${columns.slice(0,9).map(([key])=>pfCell(r,i,key)).join('')}<td class="score ${pfRPN(r)>=160?'high':pfRPN(r)>=80?'mid':''}">${pfRPN(r)??'—'}</td>${columns.slice(9).map(([key])=>pfCell(r,i,key)).join('')}<td class="score ${pfNewRPN(r)>=160?'high':pfNewRPN(r)>=80?'mid':''}">${pfNewRPN(r)??'—'}</td><td><button class="btn small danger" data-remove-fmea="${i}" title="Position entfernen">✕</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><b>Noch keine PFMEA-Einträge</b>Mit + Fehlermöglichkeit die erste Position hinzufügen und direkt bearbeiten.</div>`}<div class="callout warning"><b>* Arbeitshilfe, kein offizieller AIAG-VDA AP:</b> Die Markierung weist auf S ≥ 9 oder RPN ≥ 160 hin. Diese interne Heuristik ersetzt <b>nicht</b> die AIAG-VDA Action-Priority-Tabelle. S/O/D-Bewertungen fachlich kalibrieren und Maßnahmen unabhängig vom RPN beurteilen.</div><div class="stats" style="margin-top:16px"><div class="stat"><b>${rows.length}</b><span>Fehlermöglichkeiten</span></div><div class="stat"><b>${rows.filter(r=>pfRPN(r)!=null).length}</b><span>Bewertete Risiken</span></div><div class="stat"><b>${critical}</b><span>Priorität prüfen*</span></div><div class="stat"><b>${rows.filter(r=>pfNewRPN(r)!=null).length}</b><span>Neubewertet</span></div></div></div>`}
function pfCell(row,i,key){let isN=['s','o','d','ns','no','nd'].includes(key),date=key==='due';return `<td><input aria-label="PFMEA ${i+1}: ${esc(key)}" ${isN?'class="small-number"':''} type="${date?'date':'text'}" ${isN?'inputmode="numeric" maxlength="2"':''} data-pf="${i}:${key}" value="${esc(row[key]??'')}"></td>`}
function savedView(p){return `<div class="panel"><div class="panel-head"><div><h2>Gespeicherte Analyseergebnisse</h2><p class="sub">Snapshots der Ergebnisse zum jeweiligen Zeitpunkt; jederzeit mit aktuellen Daten neu auswertbar.</p></div><span class="tag">${p.analyses.length} Analysen</span></div>${p.analyses.length?`<div class="saved-list">${[...p.analyses].reverse().map(a=>`<div class="saved-item"><div style="color:var(--green);font-size:22px">${TOOLS[a.tool]?.[2]||'∑'}</div><div class="grow"><strong>${esc(a.title)}</strong><small>${esc(a.created_at?.replace('T',' ').slice(0,19)||'')} · ${esc(TOOLS[a.tool]?.[0]||a.tool)} · ${a.n||0} Werte</small><div class="quiet-small">${esc(a.summary||'')}</div></div><button class="btn small" data-reopen="${esc(a.id)}">Mit aktuellen Daten öffnen</button><button class="btn small danger" data-remove-run="${esc(a.id)}">✕</button></div>`).join('')}</div>`:`<div class="empty"><b>Keine gespeicherten Analysen</b>In „Analysewerkzeuge“ Parameter wählen und Ergebnis im Projekt speichern.</div>`}</div>`}
function download(name,content,type='text/plain;charset=utf-8'){let blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),4000)}
function csvQuote(v){let s=String(v??'');if(/^[=+@]/.test(s)||(/^-/ .test(s)&&!Number.isFinite(num(s))))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}
const csvLine=arr=>arr.map(csvQuote).join(';');
function csvProject(p){return [csvLine(p.dataset.columns.map(c=>c.title)),...p.dataset.rows.map(row=>csvLine(row))].join('\r\n')}
function csvPFMEA(p){let keys=['process','mode','effect','cause','prevention','detection','s','o','d','rpn','action','owner','due','ns','no','nd','residual_rpn'];return [csvLine(keys),...p.pfmea.map(r=>csvLine(keys.map(k=>k==='rpn'?pfRPN(r):k==='residual_rpn'?pfNewRPN(r):r[k]??'')))].join('\r\n')}
function parseCSV(src){let s=src.replace(/^\uFEFF/,'').replace(/\r\n?/g,'\n'),head=s.split('\n')[0]||'';let delims=['\t',';',','];let delim=delims.map(d=>({d,n:head.split(d).length})).sort((a,b)=>b.n-a.n)[0].d;let rows=[],row=[],cell='',quoted=false;for(let i=0;i<s.length;i++){let c=s[i];if(c==='"'){if(quoted&&s[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===delim&&!quoted){row.push(cell);cell=''}else if(c==='\n'&&!quoted){row.push(cell);if(row.some(v=>v.trim()))rows.push(row);row=[];cell=''}else cell+=c}row.push(cell);if(row.some(v=>v.trim()))rows.push(row);if(!rows.length)return [];let m=Math.max(...rows.map(x=>x.length));return rows.map(r=>Array.from({length:m},(_,i)=>r[i]??''))}
function addCol(p){p.dataset.columns.push({id:id(),title:'Neue Variable '+(p.dataset.columns.length+1),type:'number'});p.dataset.rows.forEach(r=>r.push(''));scheduleSave(p);render()}
function addRow(p,n=1){for(let i=0;i<n;i++)p.dataset.rows.push(p.dataset.columns.map(() => ''));scheduleSave(p);render()}
function modalProject(edit=false){let p=edit?current():null;openModal(`<form id="project-form">${label('Projektname',`<input required maxlength="150" name="title" value="${esc(p?.title||'') }" placeholder="z. B. Ausschuss Montagestraße 3">`)}${label('Ziel / Projektbeschreibung',`<textarea name="objective" maxlength="2500" rows="3" placeholder="Welche messbare Verbesserung soll erreicht werden?">${esc(p?.objective||'')}</textarea>`)}${label('Verantwortlich',`<input name="owner" value="${esc(p?.owner_name||'')}" placeholder="Projektleitung">`)}${label('DMAIC-Phase',`<select name="phase">${['Define','Measure','Analyze','Improve','Control'].map(n=>`<option value="${n}" ${p?.phase===n?'selected':''}>${n}</option>`).join('')}</select>`)}<div class="modal-footer"><button type="button" class="btn outline" data-close>Abbrechen</button><button type="submit" class="btn primary">${edit?'Änderungen speichern':'Projekt erstellen'}</button></div></form>`,edit?'Projekt bearbeiten':'Neues Six-Sigma-Projekt');$('#project-form').addEventListener('submit',e=>{e.preventDefault();const f=e.currentTarget,fd=new FormData(f),title=String(fd.get('title')||'').trim();if(!title)return;let item;if(edit){item=current();item.title=title;item.objective=String(fd.get('objective')||'');item.owner_name=String(fd.get('owner')||'');item.phase=String(fd.get('phase')||'Measure')}else{item=newProject(title,String(fd.get('objective')||''),String(fd.get('owner')||''));item.phase=String(fd.get('phase')||'Measure');state.projects.push(item);state.active=item.id;state.tab='data'}scheduleSave(item);closeModal();render();toast('Projekt gespeichert')})}
function modalCSV(mode='file'){let p=current();if(mode==='paste'){openModal(`<form id="paste-form">${label('Tabellenblock mit Überschriften (Tab / Semikolon / Komma)',`<textarea required rows="11" id="paste-area" placeholder="Messwert;Temperatur;Fehlerart&#10;52;185;Sensor&#10;48;172;Material"></textarea>`)}<p class="quiet-small">Erste Zeile = editierbare Spaltentitel. Die aktuelle Tabelle dieses Projekts wird ersetzt; andere Projekte bleiben unverändert.</p><div class="modal-footer"><button type="button" data-close class="btn outline">Abbrechen</button><button class="btn primary" type="submit">Daten übernehmen</button></div></form>`,'Datentabelle einfügen');$('#paste-form').addEventListener('submit',e=>{e.preventDefault();importRows(p,$('#paste-area').value)})}else{openModal(`<div class="field"><label>CSV-Datei mit Kopfzeile</label><input type="file" accept=".csv,text/csv,text/plain" id="csv-file"></div><div class="callout">Die CSV muss Überschriften in Zeile 1 enthalten. Beim Import wird die Datentabelle dieses Projekts ersetzt (nicht das PFMEA-Blatt).</div><div class="modal-footer"><button class="btn outline" data-close>Abbrechen</button><button class="btn primary" id="csv-go">CSV übernehmen</button></div>`,'CSV importieren');$('#csv-go').addEventListener('click',async()=>{let file=$('#csv-file').files?.[0];if(!file)return toast('Bitte Datei auswählen',true);if(file.size>2*1024*1024)return toast('Datei maximal 2 MB',true);importRows(p,await file.text())})}}
function importRows(p,text){let rows=parseCSV(text);if(rows.length<2)return toast('Kopfzeile und mindestens eine Datenzeile benötigt',true);if(rows[0].length>45||rows.length>20001)return toast('Maximal 45 Spalten und 20.000 Zeilen pro Import',true);if(!confirm('Aktuelle Datentabelle dieses Projekts ersetzen?'))return;let head=rows[0].map((s,i)=>s.trim()||'Variable '+(i+1));let data=rows.slice(1);let columns=head.map((title,j)=>({id:id(),title,type:data.filter(r=>String(r[j]).trim()).every(r=>Number.isFinite(num(r[j])))?'number':'text'}));p.dataset={columns,rows:data};p.analyses=[];state.options={};scheduleSave(p);closeModal();render();toast(`${data.length} Datenzeilen importiert; gespeicherte Analysen zurückgesetzt`) }
function importProjectJSON(text){let parsed;try{parsed=JSON.parse(text)}catch{return toast('Ungültige JSON-Datei',true)}let list=Array.isArray(parsed)?parsed:[parsed];if(!list.length||list.length>200)return toast('Keine gültigen Projekte oder zu viele Projekte',true);let added=0;for(let obj of list){if(typeof obj?.title!=='string'||!Array.isArray(obj.dataset?.columns)||!Array.isArray(obj.dataset?.rows))continue;let p=newProject(obj.title.slice(0,150),String(obj.objective||''),String(obj.owner_name||''));p.dataset={columns:obj.dataset.columns.map(c=>({id:id(),title:String(c.title||'Variable').slice(0,150),type:c.type==='text'?'text':'number'})),rows:obj.dataset.rows.slice(0,20000).map(r=>Array.isArray(r)?r.slice(0,60).map(v=>String(v??'')) : [])};if(!p.dataset.columns.length||p.dataset.columns.length>45)continue;p.dataset.rows=p.dataset.rows.map(r=>p.dataset.columns.map((_,i)=>r[i]??''));p.phase=['Define','Measure','Analyze','Improve','Control'].includes(obj.phase)?obj.phase:'Measure';p.pfmea=Array.isArray(obj.pfmea)?obj.pfmea.slice(0,1000).map(r=>({...r,id:id()})):[];p.analyses=[];state.projects.push(p);scheduleSave(p);added++}render();toast(`${added} Projekt(e) übernommen · Analysen bitte erneut berechnen`)}
async function cloudSDK(){if(globalThis.supabase?.createClient)return;await new Promise((resolve,reject)=>{let script=document.createElement('script');script.src='https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.81.1/dist/umd/supabase.js';script.onload=resolve;script.onerror=()=>reject(new Error('Supabase SDK konnte nicht geladen werden'));document.head.append(script)});if(!globalThis.supabase?.createClient)throw Error('Ungültige Supabase SDK Antwort')}
function authModal(){if(state.mode==='cloud'){openModal(`<p>Angemeldet als <b>${esc(state.user?.email||'')}</b>.</p><div class="callout">Ihre Cloud-Projekte bleiben privat. Abmeldung wechselt zurück zu lokalen Projekten.</div><div class="modal-footer"><button class="btn outline" data-close>Schließen</button><button class="btn danger" id="logout">Abmelden</button></div>`,'Cloud-Konto');$('#logout').addEventListener('click',async()=>{await state.client?.auth.signOut();state.mode='local';state.user=null;state.projects=localLoad();state.active=null;closeModal();render();toast('Abgemeldet')});return}openModal(`<form id="auth-form">${label('E-Mail',`<input type="email" required name="email" autocomplete="email">`)}${label('Passwort (min. 6 Zeichen)',`<input type="password" required minlength="6" name="password" autocomplete="current-password">`)}<div class="field"><label>Konto-Aktion</label><select name="action"><option value="login">Mit vorhandenem Konto anmelden</option><option value="register">Neues Konto anlegen</option></select></div><p class="quiet-small">Supabase E-Mail-Bestätigung kann erforderlich sein. Erst nach bestätigter Anmeldung werden Cloud-Projekte gespeichert.</p><div class="modal-footer"><button type="button" data-close class="btn outline">Abbrechen</button><button type="submit" class="btn primary">Fortfahren</button></div></form>`,'Supabase Cloud-Anmeldung');$('#auth-form').addEventListener('submit',async e=>{e.preventDefault();let f=e.currentTarget,form=new FormData(f),btn=f.querySelector('[type="submit"]');btn.disabled=true;btn.textContent='Verbindung…';try{await cloudSDK();state.client=globalThis.supabase.createClient(SUPABASE_URL,SUPABASE_KEY,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});let email=String(form.get('email')).trim(),password=String(form.get('password'));let response=form.get('action')==='register'?await state.client.auth.signUp({email,password}):await state.client.auth.signInWithPassword({email,password});if(response.error)throw response.error;if(!response.data?.session){toast('Bestätigen Sie die Registrierungs-E-Mail und melden Sie sich anschließend an.');closeModal();return}await enterCloud(response.data.session.user);closeModal();toast('Cloud-Anmeldung erfolgreich')}catch(err){toast(String(err?.message||err),true)}finally{btn.disabled=false;btn.textContent='Fortfahren'}})}
async function enterCloud(user){let {data,error}=await state.client.from('sigma_projects').select('id,title,objective,owner_name,phase,dataset,analyses,pfmea,created_at,updated_at').order('updated_at',{ascending:false});if(error)throw error;state.mode='cloud';state.user=user;state.projects=(data||[]).map(p=>({...p,analyses:Array.isArray(p.analyses)?p.analyses:[],pfmea:Array.isArray(p.pfmea)?p.pfmea:[],dataset:{columns:Array.isArray(p.dataset?.columns)?p.dataset.columns:[],rows:Array.isArray(p.dataset?.rows)?p.dataset.rows:[]}}));state.active=null;state.options={};render()}
async function restoreAuth(){try{await cloudSDK();state.client=globalThis.supabase.createClient(SUPABASE_URL,SUPABASE_KEY,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});let {data,error}=await state.client.auth.getSession();if(!error&&data?.session?.user)await enterCloud(data.session.user)}catch(err){console.warn('Cloud session unavailable:',err?.message||err)}}
function initialize(){state.projects=localLoad();render();const url=new URL(location.href);if(url.searchParams.has('error'))toast('Anmeldung: '+(url.searchParams.get('error_description')||url.searchParams.get('error')),true);restoreAuth()}
// All mutations are initiated by a user event; editing keeps each project's isolated dataset.
document.addEventListener('click',async event=>{
 const el=event.target.closest('button,a');if(!el)return;
 if(el.id==='auth-btn')return authModal();
 if(el.dataset.open){state.active=el.dataset.open;state.tab='data';state.options={};render();return}
 if(el.dataset.tab){if(!current())return modalProject();state.tab=el.dataset.tab;render();return}
 if(el.dataset.tool){if(!current())return modalProject();state.tool=el.dataset.tool;state.tab=state.tool==='pfmea'?'pfmea':'analysis';state.options={};render();return}
 if(el.dataset.removeRow!==undefined){let p=current();if(p){p.dataset.rows.splice(Number(el.dataset.removeRow),1);scheduleSave(p);render()}return}
 if(el.dataset.removeCol){let p=current(),i=p.dataset.columns.findIndex(c=>c.id===el.dataset.removeCol);if(i>=0&&p.dataset.columns.length>1&&confirm('Spalte und ihre Werte aus diesem Projekt entfernen?')){p.dataset.columns.splice(i,1);p.dataset.rows.forEach(r=>r.splice(i,1));scheduleSave(p);state.options={};render()}else if(p.dataset.columns.length<=1)toast('Mindestens eine Spalte ist erforderlich',true);return}
 if(el.dataset.removeFmea!==undefined){let p=current();if(confirm('PFMEA-Position endgültig löschen?')){p.pfmea.splice(Number(el.dataset.removeFmea),1);scheduleSave(p);render()}return}
 if(el.dataset.reopen){let p=current(),run=p?.analyses.find(a=>a.id===el.dataset.reopen);if(run){state.tool=run.tool;state.options={...run.options};state.tab='analysis';render()}return}
 if(el.dataset.removeRun){let p=current();if(confirm('Analyse-Snapshot entfernen?')){p.analyses=p.analyses.filter(a=>a.id!==el.dataset.removeRun);scheduleSave(p);render()}return}
 if(!el.dataset.action)return;
 const action=el.dataset.action,p=current();
 switch(action){
 case 'back':state.active=null;state.tab='data';render();break;
 case 'create-project':modalProject(false);break;
 case 'edit-project':modalProject(true);break;
 case 'sample-project':{let p=sampleProject();state.projects.push(p);state.active=p.id;state.tab='data';scheduleSave(p);render();toast('Fiktives Beispielprojekt erstellt');break}
 case 'delete-project':if(p&&confirm(`Projekt „${p.title}“ einschließlich Datensatz, FMEA und Analysen löschen?`)){if(await deleteProject(p)){state.active=null;render();toast('Projekt gelöscht')}}break;
 case 'add-col':if(p)addCol(p);break;
 case 'add-row':if(p)addRow(p);break;
 case 'add-5-rows':if(p)addRow(p,5);break;
 case 'paste-grid':if(p)modalCSV('paste');break;
 case 'import-csv':if(p)modalCSV('file');break;
 case 'export-csv':if(p)download((p.title||'daten').replace(/[^a-z0-9äöü_-]/gi,'_')+'.csv','\uFEFF'+csvProject(p),'text/csv;charset=utf-8');break;
 case 'export-pfmea':if(p)download('pfmea_'+p.title.replace(/[^a-z0-9_-]/gi,'_')+'.csv','\uFEFF'+csvPFMEA(p),'text/csv;charset=utf-8');break;
 case 'export-project':if(p)download('six-sigma-'+p.title.replace(/[^a-z0-9_-]/gi,'_')+'.json',JSON.stringify(p,null,2),'application/json');break;
 case 'export-all':download('six-sigma-backup-'+today()+'.json',JSON.stringify(state.projects,null,2),'application/json');break;
 case 'import-all':openModal(`<input type="file" id="json-file" accept="application/json,.json" class="field-input"><p class="quiet-small">Importiert als neue Projekt-IDs und lässt bestehende Projekte unangetastet. Analyse-Snapshots bitte danach neu berechnen.</p><div class="modal-footer"><button class="btn outline" data-close>Abbrechen</button><button class="btn primary" id="import-json-btn">Datei importieren</button></div>`,'Projekte aus JSON laden');$('#import-json-btn').addEventListener('click',async()=>{let f=$('#json-file').files?.[0];if(!f)return toast('JSON-Datei wählen',true);if(f.size>6e6)return toast('JSON-Datei max. 6 MB',true);importProjectJSON(await f.text());closeModal()});break;
 case 'save-result':if(p){let run=compute(p,state.tool,state.options);if(!run.valid)return toast('Erst gültige Daten bereitstellen',true);let snapshot={id:id(),title:String(state.options.title||TOOLS[state.tool][0]).trim(),tool:state.tool,options:{...state.options},stats:run.stats,summary:run.stats.map(s=>s[0]+': '+s[1]).slice(0,4).join(' · '),n:p.dataset.rows.filter(r=>r.some(v=>String(v??'').trim())).length,created_at:new Date().toISOString()};p.analyses.push(snapshot);scheduleSave(p);toast('Analyse-Snapshot im Projekt gespeichert');}break;
 case 'add-fmea':if(p){p.pfmea.push({id:id(),process:'',mode:'',effect:'',cause:'',prevention:'',detection:'',s:'',o:'',d:'',action:'',owner:'',due:'',ns:'',no:'',nd:''});scheduleSave(p);render()}break;
 }});
document.addEventListener('change',e=>{
 let el=e.target,p=current();if(!p)return;
 if(el.dataset.colname){let c=p.dataset.columns.find(c=>c.id===el.dataset.colname);if(c){c.title=el.value.trim().slice(0,150)||'Unbenannte Spalte';scheduleSave(p);render()}return}
 if(el.dataset.coltype){let c=p.dataset.columns.find(c=>c.id===el.dataset.coltype);if(c){c.type=el.value==='text'?'text':'number';scheduleSave(p);state.options={};render()}return}
 if(el.dataset.cell){let [i,j]=el.dataset.cell.split(':').map(Number);if(!p.dataset.rows[i]||!p.dataset.columns[j])return;p.dataset.rows[i][j]=el.value;scheduleSave(p);return}
 if(el.dataset.pf){let [row,key]=el.dataset.pf.split(':');let item=p.pfmea[Number(row)];if(!item)return;if(['s','o','d','ns','no','nd'].includes(key)&&el.value.trim()&&(!Number.isInteger(num(el.value))||num(el.value)<1||num(el.value)>10)){toast('S, O, D: ganze Zahl von 1 bis 10 erforderlich',true);el.focus();return}item[key]=el.value;scheduleSave(p);render();return}
 if(el.dataset.opt){state.options[el.dataset.opt]=el.value;if(el.dataset.opt==='test')state.options.y=state.options.y||'';render();return}
 });
initialize();